<?php require 'common.php';require_admin();$rows=array_reverse(load_json('audit',[]));admin_head('سجل العمليات');?><section class="panel"><div class="panel-head"><div><span>AUDIT TRAIL</span><h2>آخر العمليات</h2></div><b><?=count($rows)?></b></div><div class="table-wrap"><table><thead><tr><th>الوقت</th><th>العملية</th><th>التفاصيل</th><th>IP</th></tr></thead><tbody><?php foreach(array_slice($rows,0,200) as$r):?><tr><td><?=e((string)($r['time']??''))?></td><td><?=e((string)($r['action']??''))?></td><td><?=e((string)($r['detail']??''))?></td><td><?=e((string)($r['ip']??''))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="muted-cell">لا توجد عمليات مسجلة بعد.</td></tr><?php endif;?></tbody></table></div></section><?php admin_foot();?>